<script>
    let app_id = '630b3d77-5530-4854-a0e0-9fd3f08f9321'; //安装包 ID
    let query_interval = 1500; // 签名任务前台定时时间 1500 = 1.5 秒
    let open_setting_t = 1500; // 点击下载描述文件 自动打开设置间隔时间 1500 = 1.5 秒
    let auto_retry = false; // 签名失败时是否自动重试 false 为不自动重试、true 为自动重试
</script>
<script src="{{ config('api.basics.cdn') }}/theme/nuosike-qnq/js/bootstrap.min.js"></script>
<script src="{{ config('api.basics.cdn') }}/theme/nuosike-qnq/js/tishihook.js"></script>
<script src="{{ config('api.basics.cdn') }}/theme/nuosike-qnq/js/jquery-1.10.1.min.js"></script>
<script>
    document.addEventListener('DOMContentLoaded', function() {
        // 添加主题验证
        const currentDomain = window.location.hostname;
        $.ajax({
            url: `https://self-update.dvffz8.cn/api/v1/theme_auth`,
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
            },
            data: JSON.stringify({
                code: 'nuosike-qnq-theme',
                domain: currentDomain
            })
        })
            .done(function(data) {
                if (data.status === 'enable') {
                    const isIOS = /iPad|iPhone|iPod|Macintosh/.test(navigator.userAgent);
                    const isSafari = /^((?!chrome|android).)*safari/i.test(navigator.userAgent);
                    const versionRegex = /Version\/(\d+\.\d+)/;
                    const UAVMatch = navigator.userAgent.match(versionRegex);
                    const iOSVersion = UAVMatch ? UAVMatch[1] : 0;

                    var dynamicIntervalId = null;

                    if (localStorage.getItem('udid')) {
                        $("#iosudid").val(localStorage.getItem('udid'));
                    }

                    $('#getudid').on('click', function() {
                        if (!checkUA()) {
                            return false;
                        }
                        webToast('<img src="/theme/nuosike-qnq/icon/msg.png" width="18px" height="18px"><br>安装如需密码，即您的锁屏密码', "top", 3000);
                        window.location.href = '/api/udid.mobileconfig';
                        setTimeout(function() {
                            if (iOSVersion < 17.0) {
                                window.location.href = '/open.mobileprovision';
                            } else {
                                alert("温馨提示：请打开手机设置——通用——设备管理——安装全能签UDID获取描述文件");
                                return false;
                            }
                        }, open_setting_t);
                    });

                    $('#signIPA').on('click', function() {
                        // 这里是原来的signIPA函数逻辑
                        if ($('#loadinginstall').text() != '立即安装') {
                            alert($('#loadinginstall').text());
                            return false;
                        }

                        var iosudid = $("#iosudid").val().trim();
                        if (iosudid == '') {
                            if (!checkUA()) {
                                return false;
                            }
                            alert("安装的设备UDID不能为空");
                            if (confirm("是否立即获取本机设备UDID ？")) {
                                webToast('<img src="/theme/nuosike-qnq/icon/msg.png" width="18px" height="18px"><br>安装如需密码，即您的锁屏密码', "top", 3000);
                                window.location.href = '/api/udid.mobileconfig';
                                setTimeout(function() {
                                    if (iOSVersion < 17.0) {
                                        window.location.href = '/open.mobileprovision';
                                    } else {
                                        alert("温馨提示：请打开手机设置——通用——设备管理——安装全能签UDID获取描述文件");
                                        return false;
                                    }
                                }, open_setting_t)
                            }
                            return false;
                        }

                        if (!(iosudid.length == 25 || iosudid.length == 40)) {
                            alert("UDID码不正确");
                            if (!checkUA()) {
                                return false;
                            }
                            if (confirm("是否立即获取本机设备UDID？")) {
                                webToast('<img src="/theme/nuosike-qnq/icon/msg.png" width="18px" height="18px"><br>安装如需密码，即您的锁屏密码', "top", 3000);
                                window.location.href = '/api/udid.mobileconfig';
                                setTimeout(function() {
                                    if (iOSVersion < 17.0) {
                                        window.location.href = '/open.mobileprovision';
                                    } else {
                                        alert("温馨提示：请打开手机设置——通用——设备管理——安装全能签UDID获取描述文件");
                                        return false;
                                    }
                                }, open_setting_t);
                            }
                            return false;
                        }

                        $('#loadinginstall').text('正在请求安装中...');
                        var code = $("#code").val().trim();
                        var retryCount = 0; // 重试计数器
                        function sendAjaxRequest(app_id, iosudid, code, auto_retry = false) {
                            $.ajax({
                                type: 'POST',
                                url: "/api/sign_app",
                                data: {
                                    type: 'udid',
                                    app_id: app_id,
                                    udid: iosudid,
                                    code: code
                                },
                                dataType: "json",
                                success: function(result, textStatus, jqXHR) {
                                    startDynamicTimer(result.data.sign_id);
                                },
                                error: function(response) {
                                    if (retryCount < 1 && auto_retry === true) {
                                        retryCount++;
                                        console.log("请求失败，正在进行第 " + retryCount + " 次重试...");
                                        sendAjaxRequest(app_id, iosudid, code); // 递归调用自身进行重试
                                    } else {
                                        // 重试一次后仍然失败
                                        $('#loadinginstall').text('立即安装');
                                        alert(response['responseJSON'] ? response['responseJSON']['message'] : '请求失败，请稍后重试');
                                        retryCount = 0; // 重置计数器（可选）
                                    }
                                }
                            });
                        }
                        // 调用函数发起请求
                        sendAjaxRequest(app_id, iosudid, code, auto_retry);
                    });

                    function startDynamicTimer(sign_id) {
                        dynamicIntervalId = setInterval(function () {
                            $.ajax({
                                type: 'POST',
                                url: "/api/query_sign",
                                data: {
                                    sign_id: sign_id
                                },
                                dataType: "json",
                                success: function (result, textStatus, jqXHR) {
                                    clearInterval(dynamicIntervalId);
                                    $('#loadinginstall').text('立即安装');
                                    $('#upipa').html('<a href="' + result.data.sign[0].itms + '"><button style="width:70%" type="button" class="up1"><b class="item-title">完成</b></button></a>');
                                    window.location.href = result.data.sign[0].itms;
                                    return false;
                                },
                                error: function (response) {
                                    $('#loadinginstall').text('正在签名安装包...');
                                    clearInterval(dynamicIntervalId); // 清除当前定时器
                                    startDynamicTimer(sign_id); // 重新启动定时器
                                }
                            });
                        }, query_interval);
                    }

                    function checkUA() {
                        if (isIOS) {
                            if (isSafari) {
                                if (iOSVersion < 12.0) {
                                    alert('暂不支持低于 iOS 12 以下操作系统');
                                    return false;
                                } else {
                                    return true;
                                }
                            } else {
                                alert('请在 Safari 浏览器打开');
                                $('#allcode').html('<center><img src="data:image/png;base64," width="60px"><br><span style="color: #8d723f;font-size:12px;">请在【 Safari浏览器 】打开</span></center>');
                                webToast('<img src="data:image/png;base64," width="80px" height="93px"><br>Safari 浏览器<br><br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;【&nbsp;请复制地址在苹果 「 自带浏览器 」 访问安装&nbsp;】&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<br><br>', "middle", 5000);
                                return false;
                            }
                        } else {
                            alert('仅支持iOS操作系统');
                            return false;
                        }
                    }
                } else {
                    const message = data.message || '授权验证失败';
                    alert(message);
                }
            })
            .fail(function(error) {
                const message = error['responseJSON']['message'] || '网络异常，无法验证主题授权';
                alert(message);
            });
    });
</script>
</html>
